import Redis from 'ioredis';
const redis = new Redis();

const STREAM = 'events';
const GROUP = 'workers';
const CONSUMER = `worker-${process.pid}`;

// Ensure group exists
try {
  await redis.xgroup('CREATE', STREAM, GROUP, '$', 'MKSTREAM');
} catch (e) {
  if (!e.message.includes('BUSYGROUP')) throw e;
}

async function processMessages() {
  while (true) {
    // Read up to 10 new messages, block for 2 seconds if none
    const results = await redis.xreadgroup(
      'GROUP', GROUP, CONSUMER,
      'COUNT', 10,
      'BLOCK', 2000,
      'STREAMS', STREAM, '>'
    );

    if (!results) continue;  // timeout, loop again

    for (const [stream, messages] of results) {
      for (const [id, fields] of messages) {
        const data = Object.fromEntries(
          fields.reduce((acc, _, i, arr) => i % 2 === 0 ? [...acc, [arr[i], arr[i + 1]]] : acc, [])
        );

        try {
          await handleEvent(data);
          await redis.xack(STREAM, GROUP, id);  // mark as done
        } catch (err) {
          console.error('Failed to process', id, err);
          // Don't ACK — stays in PEL for recovery
        }
      }
    }
  }
}

processMessages();

async function recoverStuckMessages() {
  // Find messages pending for more than 60 seconds
  const pending = await redis.xpending(STREAM, GROUP, '-', '+', 50);

  for (const [id, consumer, idleMs] of pending) {
    if (idleMs > 60000) {
      // Claim the message for this worker
      await redis.xclaim(STREAM, GROUP, CONSUMER, 60000, id);
      console.log(`Reclaimed stuck message ${id} from ${consumer}`);
    }
  }
}
